practical-byzantine-fault-tolerance.pseudocode:
class Replica:  # 전체 n = 3f + 1, 결함 f개 허용
    def on_pre_prepare(self, v, seq, req):
        if v == self.view and seq not in self.log:
            self.log[seq] = req  # 프라이머리가 정한 순서
            self.broadcast('PREPARE', v, seq, digest(req))

    def on_prepare(self, v, seq, d, sender):
        self.prepares[seq].add(sender)  # 다이제스트 일치 가정
        # pre-prepare + 서로 다른 2f개 prepare → prepared
        if len(self.prepares[seq]) == 2 * self.f:
            self.broadcast('COMMIT', v, seq, d)

    def on_commit(self, v, seq, d, sender):
        self.commits[seq].add(sender)
        # 자신 포함 2f+1개 commit → 확정·실행
        if len(self.commits[seq]) == 2 * self.f + 1:
            req = self.log[seq]
            self.reply(req.client, self.execute(req))

precedence-graph.pseudocode:
def precedence_graph(schedule):  # [(txn, op, item)]
    edges = set()
    for i, (ti, oi, xi) in enumerate(schedule):
        for tj, oj, xj in schedule[i + 1:]:
            conflict = xi == xj and 'w' in (oi, oj)
            if ti != tj and conflict:
                edges.add((ti, tj))  # Ti 연산이 먼저
    return edges

def serial_order(txns, edges):  # Kahn 위상 정렬
    indeg = {t: 0 for t in txns}
    for _, v in edges:
        indeg[v] += 1
    q = [t for t in txns if indeg[t] == 0]
    order = []
    while q:
        t = q.pop(0)
        order.append(t)
        for u, v in edges:
            if u == t:
                indeg[v] -= 1
                if indeg[v] == 0:
                    q.append(v)
    # 전부 정렬되면 직렬 가능, 남으면 사이클
    return order if len(order) == len(txns) else None

prediction-by-partial-matching.pseudocode:
def ppm_encode(sym, hist, model, k, coder):
    # model[ctx] = {기호: 빈도}, ctx는 직전 문자열
    for order in range(min(k, len(hist)), -1, -1):
        ctx = hist[len(hist) - order:]  # 직전 order개
        freq = model.get(ctx)
        if not freq:
            continue  # 처음 보는 문맥: 바로 낮춤
        if sym in freq:
            coder.encode(sym, freq)  # 산술 부호화
            break
        coder.encode_escape(freq)  # Escape 후 저차로
    else:
        coder.encode_uniform(sym)  # order -1
    for order in range(min(k, len(hist)) + 1):
        ctx = hist[len(hist) - order:]  # 모델 갱신
        f = model.setdefault(ctx, {})
        f[sym] = f.get(sym, 0) + 1

priority-inheritance-protocol.pseudocode:
# 단순화: 태스크당 뮤텍스 1개 보유 가정
def lock(task, m):
    if m.owner is None:
        m.owner = task
        return
    m.waiters.append(task)
    if m.owner.prio < task.prio:
        m.owner.prio = task.prio  # 대기자 우선순위 상속
    block(task)

def unlock(task, m):
    task.prio = task.base_prio  # 원래 우선순위 복귀
    if m.waiters:
        nxt = max(m.waiters, key=lambda t: t.prio)
        m.waiters.remove(nxt)
        m.owner = nxt
        wake(nxt)
    else:
        m.owner = None

priority-queuing.pseudocode:
def enqueue(queues, pkt, classify):
    level = classify(pkt)  # 0=High … 3=Low
    if len(queues[level]) >= QUEUE_LIMIT:
        return 'drop'  # 큐 가득 → 테일 드롭
    queues[level].append(pkt)
    return 'ok'

def dequeue(queues):  # 엄격 우선순위
    for q in queues:  # High부터 검사
        if q:
            return q.popleft()
    return None  # 하위 큐는 상위가 빌 때만 → 기아 가능

process-mining.pseudocode:
def discover_dfg(event_log):
    # event_log: [(case_id, activity, timestamp), ...]
    traces = {}
    for case, act, ts in sorted(event_log,
                                key=lambda e: (e[0], e[2])):
        traces.setdefault(case, []).append(act)  # 케이스별 순서
    dfg = {}  # (a, b): 활동 a 바로 뒤에 b가 나온 횟수
    for acts in traces.values():
        for a, b in zip(acts, acts[1:]):
            dfg[(a, b)] = dfg.get((a, b), 0) + 1
    return dfg  # 빈도 임계치로 걸러 프로세스 맵 생성

# 적합성 검사: 모델에 없는 (a, b) 전이가 편차 후보

progressive-web-app.pseudocode:
def on_fetch(request):  # 서비스 워커 fetch 이벤트
    cached = cache.match(request)
    if cached:
        return cached  # 캐시 우선 → 오프라인에서도 응답
    try:
        resp = network.fetch(request)
        cache.put(request, resp.clone())  # 다음을 위해 저장
        return resp
    except NetworkError:
        return cache.match('/offline.html')  # 대체 페이지

