protection-proxy.pseudocode:
class ProtectionProxy(Subject):
    def __init__(self, real, user):
        self.real = real  # 실제 객체는 보안 로직 모름
        self.user = user

    def request(self, op):
        if not self.check_access(op):  # 접근 제어 분리
            raise PermissionError('접근 거부')
        return self.real.request(op)  # 권한 통과 시 위임

    def check_access(self, op):
        # 역할·권한 기반 인가
        return op in self.user.role.permissions

protocol-buffers.pseudocode:
def encode_varint(n):  # 7비트씩, 하위 그룹부터
    out = []
    while True:
        b = n & 0x7F
        n >>= 7
        if n:
            out.append(b | 0x80)  # MSB=1: 다음 바이트 있음
        else:
            out.append(b)  # MSB=0: 마지막 바이트
            return bytes(out)

def encode_field(field_no, value):  # varint 필드
    tag = (field_no << 3) | 0  # 필드번호 + 와이어타입 0
    return encode_varint(tag) + encode_varint(value)

# encode_field(1, 150) → 08 96 01 (3바이트)

prototype-pattern.diagram:
classDiagram
  class Prototype {
    <<interface>>
    +clone() Prototype
  }
  class ConcretePrototypeA {
    -field
    +clone() Prototype
  }
  class ConcretePrototypeB {
    -field
    +clone() Prototype
  }
  class PrototypeRegistry {
    -items Map
    +register(key, proto)
    +create(key) Prototype
  }
  class Client {
    +operation()
  }
  Prototype <|.. ConcretePrototypeA
  Prototype <|.. ConcretePrototypeB
  PrototypeRegistry o-- Prototype : 원형 보관
  Client ..> PrototypeRegistry : create(key)
  Client ..> Prototype : clone() 호출

prototype-pattern.pseudocode:
class Shape:  # Prototype
    def clone(self):
        raise NotImplementedError

class Circle(Shape):  # ConcretePrototype
    def __init__(self, r, tags):
        self.r = r
        self.tags = tags  # 참조형 필드
    def clone(self):
        # 깊은 복사: 참조형 필드도 새로 만든다
        return Circle(self.r, list(self.tags))

class Registry:  # 프로토타입 레지스트리
    def __init__(self):
        self.items = {}
    def register(self, key, proto):
        self.items[key] = proto
    def create(self, key):
        # 구체 클래스를 몰라도 복제로 생성
        return self.items[key].clone()

