def FindProxyForURL(url, host):  # 실제는 JavaScript
    if is_plain_host_name(host):
        return 'DIRECT'  # 점 없는 내부 호스트
    if dns_domain_is(host, '.corp.local'):
        return 'DIRECT'  # 사내 도메인 직접
    ip = dns_resolve(host)
    if is_in_net(ip, '10.0.0.0', '255.0.0.0'):
        return 'DIRECT'  # 사설망 대역 직접
    # 외부: 앞 프록시 장애 시 다음 항목 순차 시도
    return 'PROXY p1:8080; PROXY p2:8080; DIRECT'

